from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-051"

